import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out,
    const int K,
    const int stride,
    const int padding,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias)
{
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long total = (long)batch_size * out_channels * D_out * H_out * W_out;
    if (idx >= total) return;

    // decompose idx
    int ow = idx % W_out;
    long tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp = tmp / H_out;
    int od = tmp % D_out;
    tmp = tmp / D_out;
    int oc = tmp % out_channels;
    int b = tmp / out_channels;

    int g = oc / out_channels_per_group;
    int oc_local = oc % out_channels_per_group;
    int ic_start = g * in_channels_per_group;

    float sum = 0.0f;

    for (int ic_local = 0; ic_local < in_channels_per_group; ic_local++) {
        int ic = ic_start + ic_local;
        const float* input_bc = input + ((long)b * in_channels + ic) * D_in * H_in * W_in;
        const float* weight_c = weight + ((long)ic * out_channels_per_group + oc_local) * K * K * K;

        for (int kd = 0; kd < K; kd++) {
            int id_val = od + padding - kd;
            if (id_val % stride != 0) continue;
            int id = id_val / stride;
            if (id < 0 || id >= D_in) continue;

            for (int kh = 0; kh < K; kh++) {
                int ih_val = oh + padding - kh;
                if (ih_val % stride != 0) continue;
                int ih = ih_val / stride;
                if (ih < 0 || ih >= H_in) continue;

                for (int kw = 0; kw < K; kw++) {
                    int iw_val = ow + padding - kw;
                    if (iw_val % stride != 0) continue;
                    int iw = iw_val / stride;
                    if (iw < 0 || iw >= W_in) continue;

                    float in_val = input_bc[(long)id * H_in * W_in + ih * W_in + iw];
                    float w_val = weight_c[kd * K * K + kh * K + kw];
                    sum += in_val * w_val;
                }
            }
        }
    }

    if (has_bias) {
        sum += bias[oc];
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    if (has_bias) {
        bias = bias.contiguous();
    }

    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);

    const int out_channels_per_group = weight.size(1);
    const int K = weight.size(2);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;

    const int D_out = (D_in - 1) * stride - 2 * padding + K + output_padding;
    const int H_out = (H_in - 1) * stride - 2 * padding + K + output_padding;
    const int W_out = (W_in - 1) * stride - 2 * padding + K + output_padding;

    auto output = torch::zeros({batch_size, out_channels, D_out, H_out, W_out}, input.options());

    long total = (long)batch_size * out_channels * D_out * H_out * W_out;
    const int threads = 256;
    const long blocks = (total + threads - 1) / threads;

    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;

    conv_transpose3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        K,
        stride,
        padding,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias
    );

    return output;
}
"""

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.has_bias = bias

        # Weight shape matches nn.ConvTranspose3d: (in_channels, out_channels/groups, k, k, k)
        self.weight = nn.Parameter(torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size))
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

        self.conv_transpose3d_cuda = conv_transpose3d_module.conv_transpose3d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        if self.has_bias:
            bias = self.bias.contiguous().cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return self.conv_transpose3d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.output_padding, self.groups, self.has_bias
        )

